window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b22b86d8b9f56e68"]={"versions": [{"id": "FIG-b22b86d8b9f56e68", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Architektur-Kompositionsdiagramm des AUTOSAR-Hardware-Ressourcenmodells (ECU Resource Template). Dargestellt ist das Zusammenspiel von Hardware-Komponenten („HW Element“) innerhalb eines hierarchischen Hardware-Behälters („HW Container“) sowie deren Verschaltung über Hardware-Ports („HW Port“), interne Verbindungen („Assembly HW Connection“) und externe Pin-Anbindungen („HW Pin“, „Delegation HW Connection“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>HW Container</strong>: Umschließender Strukturknoten (Kapselungseinheit) für untergeordnete Hardware-Elemente mit externer Begrenzungslinie.\n</li><li><strong>HW Element</strong>: Rechteckige Komponentenblöcke, die diskrete Hardwarebausteine innerhalb des HW Containers repräsentieren.\n</li><li><strong>HW Port</strong>: An den Rändern der HW Elements angeordnete Anschlussstellen zur Signalführung/Kopplung.\n</li><li><strong>Assembly HW Connection</strong>: Verbindungslinie zwischen zwei HW Ports unterschiedlicher HW Elements innerhalb desselben HW Containers.\n</li><li><strong>HW Pin</strong>: Am äußeren Rand des HW Containers platzierter Schnittstellenanschluss (mit internen Leiterbahn-/Pin-Symbolen) zur Außenanbindung.\n</li><li><strong>Delegation HW Connection</strong>: Gewinkelte Verbindungslinie von einem HW Port eines internen HW Elements zum äußeren HW Pin des HW Containers.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauf- oder Sequenzcharakteristik. Die Verbindungen („Assembly HW Connection“ und „Delegation HW Connection“) modellieren dauerhafte hardwareseitige Signal- bzw. Verdrahtungspfade zwischen internen Ports sowie zwischen internen Ports und den Gehäuse-/Steckerpins des Containers.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die strukturellen Modellierungskonzepte für Hardware-Topologien im AUTOSAR ECU Resource Template. Modellierer müssen zwischen internen Punkt-zu-Punkt-Verbindungen (Assembly HW Connection zwischen zwei HW Ports) und hierarchischen Weiterleitungen an externe Schnittstellen (Delegation HW Connection zwischen HW Port und äußerem HW Pin des HW Containers) unterscheiden.</p>"}, {"id": "FIG-2cdde7ab0d907f2f", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Architektur-Kompositionsdiagramm des AUTOSAR-Hardware-Ressourcenmodells (ECU Resource Template). Dargestellt ist das Zusammenspiel von Hardware-Komponenten („HW Element“) innerhalb eines hierarchischen Hardware-Behälters („HW Container“) sowie deren Verschaltung über Hardware-Ports („HW Port“), interne Verbindungen („Assembly HW Connection“) und externe Pin-Anbindungen („HW Pin“, „Delegation HW Connection“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>HW Container</strong>: Äußere Begrenzungslinie, oben und unten im Bildausschnitt beschnitten; umschließt die internen HW Elements.\n</li><li><strong>HW Element</strong>: Rechteckige Komponentenblöcke zur Repräsentation diskreter Hardwarebausteine.\n</li><li><strong>HW Port</strong>: An den Kanten der HW Elements angebrachte Anschlusselemente für Verbindungen.\n</li><li><strong>Assembly HW Connection</strong>: Horizontale Verbindungslinie zwischen zwei HW Ports benachbarter HW Elements (untere Beschriftungszeile am unteren Rand beschnitten).\n</li><li><strong>HW Pin</strong>: Am rechten Rand angeordneter Anschlussblock (mit Pin-Markierungen und Teilbeschriftung „HW“) zur Außenanbindung.\n</li><li><strong>Delegation HW Connection</strong>: Gewinkelte Verbindungslinie von einem HW Port eines internen HW Elements zum rechten Randanschluss (HW Pin).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauf- oder Sequenzcharakteristik. Die Verbindungen („Assembly HW Connection“ und „Delegation HW Connection“) modellieren dauerhafte hardwareseitige Signal- bzw. Verdrahtungspfade zwischen internen Ports sowie zwischen internen Ports und den Gehäuse-/Steckerpins des Containers.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die strukturellen Modellierungskonzepte für Hardware-Topologien im AUTOSAR ECU Resource Template. Modellierer müssen zwischen internen Punkt-zu-Punkt-Verbindungen (Assembly HW Connection zwischen zwei HW Ports) und hierarchischen Weiterleitungen an externe Schnittstellen (Delegation HW Connection zwischen HW Port und äußerem HW Pin des HW Containers) unterscheiden.</p>"}, {"id": "FIG-32a719d771f92b17", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Architektur-Kompositionsdiagramm des AUTOSAR-Hardware-Ressourcenmodells (ECU Resource Template). Dargestellt ist das Zusammenspiel von Hardware-Komponenten („HW Element“) innerhalb eines hierarchischen Hardware-Behälters („HW Container“) sowie deren Verschaltung über Hardware-Ports („HW Port“), interne Verbindungen („Assembly HW Connection“) und externe Pin-Anbindungen („HW Pin“, „Delegation HW Connection“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>HW Container</strong>: Äußere Begrenzungslinie, oben und unten im Bildausschnitt beschnitten; umschließt die internen HW Elements.\n</li><li><strong>HW Element</strong>: Rechteckige Komponentenblöcke zur Repräsentation diskreter Hardwarebausteine.\n</li><li><strong>HW Port</strong>: An den Kanten der HW Elements angebrachte Anschlusselemente für Verbindungen.\n</li><li><strong>Assembly HW Connection</strong>: Horizontale Verbindungslinie zwischen zwei HW Ports benachbarter HW Elements (untere Beschriftungszeile am unteren Rand beschnitten).\n</li><li><strong>HW Pin</strong>: Am rechten Rand angeordneter Anschlussblock (mit Pin-Markierungen und Teilbeschriftung „HW“) zur Außenanbindung.\n</li><li><strong>Delegation HW Connection</strong>: Gewinkelte Verbindungslinie von einem HW Port eines internen HW Elements zum rechten Randanschluss (HW Pin).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauf- oder Sequenzcharakteristik. Die Verbindungen („Assembly HW Connection“ und „Delegation HW Connection“) modellieren dauerhafte hardwareseitige Signal- bzw. Verdrahtungspfade zwischen internen Ports sowie zwischen internen Ports und den Gehäuse-/Steckerpins des Containers.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die strukturellen Modellierungskonzepte für Hardware-Topologien im AUTOSAR ECU Resource Template. Modellierer müssen zwischen internen Punkt-zu-Punkt-Verbindungen (Assembly HW Connection zwischen zwei HW Ports) und hierarchischen Weiterleitungen an externe Schnittstellen (Delegation HW Connection zwischen HW Port und äußerem HW Pin des HW Containers) unterscheiden.</p>"}], "trans": [{"from": "FIG-b22b86d8b9f56e68", "to": "FIG-2cdde7ab0d907f2f", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Gesamtes Diagramm: Bildbeschnitt bzw. Darstellungsbereich ist vertikal und horizontal verkleinert; oberer und unterer Rand des umschließenden Rahmens sowie die Beschriftung „HW Container“ sind abgeschnitten.\n</li><li>Beschriftung „Assembly HW Connection“: untere Textzeile am unteren Bildrand abgeschnitten.\n</li><li>Beschriftung „HW Pin“: Beschriftung oben rechts zu „HW“ abgeschnitten.\n</li></ul>"}, {"from": "FIG-2cdde7ab0d907f2f", "to": "FIG-32a719d771f92b17", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
